const s = wb.getWorksheet('Sheet1');
const f = (r, n) => `=INDEX(Sheet1!$M$7:$N$13,AGGREGATE(15,6,(ROW(Sheet1!$L$7:$L$13)-ROW(Sheet1!$L$7)+1)/(Sheet1!$L$7:$L$13=Sheet1!$C${r}),INT((${n}+1)/2)),2-MOD(${n},2))`;
const out = [];
for (const [r,n] of [[7,1],[7,2],[7,3],[7,4],[8,1],[8,2],[9,1],[9,2],[9,3],[9,4],[10,1],[11,1]]) out.push(`row ${r} n${n}: ${await wb.evaluate(f(r,n))}`);
log(out.join('\n'));
const lens = wb.getRange('Sheet1!C7:C11').getValues().map(a=>JSON.stringify(a[0]));
const l2 = wb.getRange('Sheet1!L7:N11').getValues().map(a=>JSON.stringify(a));
log(lens.join(' '), l2.join(' '));
log(wb.getRange('Sheet1!D7:D11').getValues().map(a=>a[0]).join('|'), s.getName());
log(wb.getRange('Sheet1!D8').getStyle().getNumberFormat?.());

