for (const r of [8,9,10,11]) wb.getRange(`Sheet1!D${r}`).setValue(`=INDEX($M$7:$N$13,AGGREGATE(15,6,(ROW($L$7:$L$13)-ROW($L$7)+1)/($L$7:$L$13=$C${r}),INT((COLUMNS($D${r}:D${r})+1)/2)),2-MOD(COLUMNS($D${r}:D${r}),2))`);
const out = [];
for (const r of [7,8,9,10,11]) { const c = wb.getRange(`Sheet1!D${r}`).getCell(); out.push(`D${r}: ${JSON.stringify(wb.getRange(`Sheet1!D${r}`).getValues()[0][0])} | ${c.getText()} | ${c.getFormula?.() ?? ''}`); }
log(out.join('\n'));
